INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (1, 1, 1, 'Protege A3H', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/al_harrington/protege_a3h/protege_a3h.jpg&w=712&h=480', 2009, 'Obscure', 'Al Harrington released the only signature model of his 16-year career under his own footwear brand, Protege, that he launched in 2008 as an affordable alternative to big sneaker companies. By early 2009, the Protege A3H hit retail for $34.99, exclusively sold at Kmart, which also donated 1 million pairs to the Samaritan’s Feet nonprofit on behalf of Harrington''s brand mission.', 'protege-a3h') ON CONFLICT (shoe_id) DO NOTHING;
