INSERT INTO brand (brand_id, name) VALUES (2, 'Reebok') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (2, 1, 'Allen Iverson', false) ON CONFLICT DO NOTHING;
INSERT INTO tag (tag_id, label, status_type) VALUES (2, 'Iconic', 'Iconic') ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (2, 2, 2, 'Reebok Question/Solution', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/allen_iverson/reebok_question_solution/reebok_question_solution.jpg&w=712&h=480', 1996, 'Iconic', 'In 1996, Allen Iverson turned down Nike to join Reebok on a 10-year, $60 million endorsement contract — the richest sneaker deal in the history of the NBA at the time. Ultimately, Reebok landed Iverson with a signature shoe ready for the No. 1 overall pick to begin his rookie year wearing. Nike’s shoe for Iverson — planned as the Air Bubba Chuck — became the Air Turbulence, released after A.I. debuted the red toe-boxed Reebok Question. Since its February 1997 retail release, the Question has persisted as one of the most iconic models in Reebok history — a shoe that took seven years to get a second edition. Following the Question II (2004) and Question III (2007), Reebok unveiled the Iverson Solution in 2022 as a price-friendly final installment to the series.', 'reebok-questionsolution') ON CONFLICT (shoe_id) DO NOTHING;
