INSERT INTO brand (brand_id, name) VALUES (4, 'Adidas') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (4, 1, 'Anthony Edwards', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (4, 4, 4, 'Adidas AE', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/anthony_edwards/adidas_ae/adidas_ae.jpg&w=712&h=480', 2023, 'Standard', 'Before lacing up his first signature model in a single game, Anthony Edwards tried to tell us he already had the best shoe in the NBA. “You know how I know? ’Cause they mine. Believe that,” the 22-year-old Minnesota Timberwolves star proclaimed in the commercial unveil for his Adidas AE 1. Edwards delivered on the declaration for the debut signature he fatefully wore throughout his prolific 2023-24 second-team All-NBA season, during which many swiftly considered the Adidas AE 1 the league’s best shoe. Some even credited Edwards for Adidas’ stock increase in the months following the AE 1’s December 2023 retail release. Entire rollout considered — from memorable launch marketing to continuously cool colorways and Ant Man’s sales-sparking rise to superstardom — the AE 1 presents a believably strong case as one of the best signature debuts in NBA history.', 'adidas-ae') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (14, 4, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/anthony_edwards/adidas_ae/adidas_ae.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (11, 4, 'Adidas AE 1 Low', 2024, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/anthony_edwards/adidas_ae/models/adidas_ae_1_low.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (15, 4, 11, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/anthony_edwards/adidas_ae/models/adidas_ae_1_low.jpg&w=712&h=480', 'gallery') ON CONFLICT (image_id) DO NOTHING;
