INSERT INTO brand (brand_id, name) VALUES (5, 'Nike') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (5, 1, 'Alonzo Mourning', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (5, 5, 5, 'Nike Air Alonzo', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/alonzo_mourning/nike_air_alonzo/nike_air_alonzo.jpg&w=712&h=480', 1997, 'Standard', 'Former longtime Nike footwear designer Aaron Cooper found beauty and conflicting challenge in building footwear for 15-year NBA center Alonzo Mourning. Nearly two decades after designing both signature models of Mourning''s career, Cooper described the Hall of Famer''s former 6-foot-10, 260-pound physique poetically. “Calves like bowling balls, wingspan like an albatross, shoulder-to-hips ratio like an isosceles triangle,” Cooper posted on Instagram. Following Mourning''s 1997 debut shoe, the Nike Air Alonzo, Cooper ramped up his next design, introducing new tech and comfier materials, on 1998''s Air Zo Tuff. Ultimately though, Nike and Cooper couldn''t quite completely problem solve for Mourning, whose signature line short-stinted after the second and final Zo Tuff model. “We realized the design was simply not enough for the force of Zo,” Cooper recalled. “There are concepts from the past I would certainly like to try again … This is one.”', 'nike-air-alonzo') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (17, 5, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/alonzo_mourning/nike_air_alonzo/nike_air_alonzo.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (13, 5, 'Nike Air Zo Tuff', 1998, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/alonzo_mourning/nike_air_alonzo/models/nike_air_zo_tuff.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (18, 5, 13, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/alonzo_mourning/nike_air_alonzo/models/nike_air_zo_tuff.jpg&w=712&h=480', 'gallery') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (14, 5, 'Nike Air Alonzo', 1997, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/alonzo_mourning/nike_air_alonzo/models/nike_air_alonzo.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
