INSERT INTO brand (brand_id, name) VALUES (6, 'Peak') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (6, 1, 'Andrew Wiggins', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (6, 6, 6, 'Peak AW', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/andrew_wiggins/peak_aw/peak_aw.jpg&w=712&h=480', 2023, 'Standard', 'After Peak signed Andrew Wiggins to a signature deal in 2020, it took the Chinese brand three years to release the 2014 No. 1 overall pick’s debut shoe. Oddly, in the meantime, the Golden State Warriors swingman played multiple games, including throughout the 2022 NBA Finals, in pairs of the late Kobe Bryant’s signature Nike line. Maintaining brand loyalty, he duct-taped over all swoosh logos. Finally, last year, Peak delivered not one but three different models to Wiggins, who became the eighth NBA signature headliner in brand history. Peak and Wiggins rolled out the AW 1 and 2, as well as an off-court lifestyle shoe called the Mimic, all within a four-month stretch in 2023.', 'peak-aw') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (20, 6, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/andrew_wiggins/peak_aw/peak_aw.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
