INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (7, 1, 'Antoine Walker', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (7, 4, 7, 'Adidas Real Deal', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/antoine_walker/adidas_real_deal/adidas_real_deal.jpg&w=712&h=480', 1998, 'Standard', 'Drafted sixth overall by the Celtics in 1996, Antoine Walker brought foreign flavor to an extremely traditionalist franchise. Walker arrived in Boston with his trademark “Shimmy” — an on-court celebration he often broke out while laced in sneakers that also became a signature of his. In 1998, Walker headlined print ads for the Adidas Equipment Real Deal, crafted with the brand’s “Feet You Wear” design and tech that functioned to perform like a player’s natural foot. Walker also starred in his own’ “Employee No. 8” Adidas commercial promoting the Real Deal, then marketed as basketball’s lightest shoe — perfect, in theory, for the Celtics forward''s shimmying. Released in 1999, the Real Deal II didn''t offically have Walker''s name attached but became culturally known as the “AW8" because of the holograms of his initials featured on each shoe''s heel.', 'adidas-real-deal') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (24, 7, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/antoine_walker/adidas_real_deal/adidas_real_deal.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (18, 7, 'Adidas AW8', 1999, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/antoine_walker/adidas_real_deal/models/adidas_aw8.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
