INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (19, 7, 'Adidas Real Deal', 1998, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/antoine_walker/adidas_real_deal/models/adidas_real_deal.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
