INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (8, 2, 2, 'Reebok Answer', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/allen_iverson/reebok_answer/reebok_answer.jpg&w=712&h=480', 1997, 'Iconic', 'Following the Question, Reebok couldn’t fully replicate the unquestionable success of Iverson’s signature debut with his second shoe, which launched under a different name, thus introducing a separate line. Reebok’s the Answer flopped when it debuted around Thanksgiving 1997, featuring a hidden lacing system and new tech that increased the price from the Question by $15. Though the first silhouette has aged well, most regard the Answer IV as the marquee model of the line that lasted until 2014. The Answer IV is the shoe Iverson wore when he stepped over Tyronn Lue in the NBA Finals during his MVP season in 2001. Later that year, Reebok extended a lifetime deal to A.I., who became the brand’s VP of basketball in 2023.', 'reebok-answer') ON CONFLICT (shoe_id) DO NOTHING;
