INSERT INTO brand (brand_id, name) VALUES (7, 'Rigorer') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (8, 1, 'Austin Reaves', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (9, 7, 8, 'Rigorer AR', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/austin_reaves/rigorer_ar1/rigorer_ar1.jpg&w=712&h=480', 2023, 'Standard', 'What happens when you''re an undrafted 6-foot-5 dude who makes the league, balls out and sparks Taylor Swift dating rumors? In the case of Los Angeles Lakers guard Austin Reaves, an emerging footwear company came calling with a seven-figure signature shoe deal. In 2022, Reaves became the first-ever NBA endorser for the Chinese brand Rigorer. Less than a year later, he laced up his debut signature, the Rigorer AR1, in approximately 10 different colorways throughout the 2023-24 NBA season. Rigorer also gave Reaves multiple editions of his own off-court rubber runner, comprable to a Croc, dubbed the Dongdong. With all due respect, Reaves will hold the crown as this database''s most-unlikely active signature headliner until further notice.', 'rigorer-ar') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (42, 9, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/austin_reaves/rigorer_ar1/rigorer_ar1.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
