INSERT INTO brand (brand_id, name) VALUES (8, 'Li-Ning') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (9, 1, 'Baron Davis', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (10, 8, 9, 'Li-Ning BD Doom', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/baron_davis/li_ning_bd_doom/li_ning_bd_doom.jpg&w=712&h=480', 2010, 'Standard', 'A color-coordinated headband and bushy beard became statements of swag synonymous with Baron “B. Diddy” Davis during his 13-year NBA career. So, fittingly in 2010, when Li-Ning unveiled his debut BD Doom shoe, the Chinese brand introduced a cartoon illustration of Davis’ banded-and-bearded head as the signature logo for all his footwear. Before the end of 2010, Davis received three more logo-embossed shoes, from the BD Doom II, to a low-top version of the original BD Doom, and finally the debut of the BD Defend model that adopted a new name in tandem with the last signature of his career, the BD Conquer. Davis’ Li-Ning line ended in 2011 following a solid five-model run built for the big-smiling and bouncy guard.', 'li-ning-bd-doom') ON CONFLICT (shoe_id) DO NOTHING;
