INSERT INTO brand (brand_id, name) VALUES (9, 'AND1') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (10, 1, 'Ben Wallace', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (11, 9, 10, 'AND1 Chosen One', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/ben_wallace/and1_chosen_one/and1_chosen_one.jpg&w=712&h=480', 2003, 'Standard', 'Four years after his debut AND1 Chosen One shoe, Ben Wallace received a second signature under fellow NBA player Stephon Marbury’s footwear brand, Starbury. In 2007, Wallace became the first and only player to receive a Starbury outside of Marbury, another former AND1 signature headliner who ultimately teamed with Steven & Barry’s to launch his own low-budget line. Basically copy-and-pasting Wallace’s AND1 Chosen One design, the Starbury Big Ben retailed for only $14.98 — an eighth of the price of his $90 first shoe. Wallace’s Starbury silhouette and box also notably featured custom signature logos, which he didn’t receive from AND1.', 'and1-chosen-one') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (49, 11, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/ben_wallace/and1_chosen_one/and1_chosen_one.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (39, 11, 'AND1 Chosen One', 2003, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/ben_wallace/and1_chosen_one/models/and1_chosen_one.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
