INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (12, 10, 10, 'Starbury Big Ben', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/ben_wallace/starbury_big_ben/starbury_big_ben.jpg&w=712&h=480', 2007, 'Obscure', 'Four years after his debut AND1 Chosen One shoe, Ben Wallace received a second signature under fellow NBA player Stephon Marbury’s footwear brand, Starbury. In 2007, Wallace became the first and only player to receive a Starbury outside of Marbury, another former AND1 signature headliner who ultimately teamed with Steven & Barry’s to launch his own low-budget line. Basically copy-and-pasting Wallace’s AND1 Chosen One design, the Starbury Big Ben retailed for only $14.98 — an eighth of the price of his $90 first shoe. Wallace’s Starbury silhouette and box also notably featured custom signature logos, which he didn’t receive from AND1.', 'starbury-big-ben') ON CONFLICT (shoe_id) DO NOTHING;
