INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (13, 11, 11, 'Grosby Black Superman', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/billy_ray_bates/grosby_black_superman/grosby_black_superman.jpg&w=712&h=480', 1983, 'Obscure', 'Bates had a brief but tumultuous NBA career but made a name for himself in the basketball-obsessed nation of the Philippines. Local company Grosby named his sneaker after the nickname of the high-flying guard.', 'grosby-black-superman') ON CONFLICT (shoe_id) DO NOTHING;
