INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (14, 12, 12, 'PF All-American', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/bob_cousy/pf_bob_cousy_all_american/pf_bob_cousy_all_american.jpg&w=712&h=480', 1960, 'Standard', 'Bob Cousy signed his basketball sneaker endorsement deal in 1958. The simple canvas sneaker was made with the most advanced performance tech available at the time, which included a circular grip pattern on the vulcanized rubber sole, as well as a wider outsole designed to provide more contact with the hardwood.', 'pf-all-american') ON CONFLICT (shoe_id) DO NOTHING;
