INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (18, 16, 15, 'UA Black Ice', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/brandon_jennings/under_armour_micro_g/under_armour_micro_g.jpg&w=712&h=480', 2010, 'Obscure', 'Brandon Jennings was a trendsetter in more ways than one. In addition to skipping college to play a year of pro ball in Italy before getting drafted into the NBA, he was also the first basketball player to sign with Under Armour in 2008.', 'ua-black-ice') ON CONFLICT (shoe_id) DO NOTHING;
