INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (19, 17, 16, 'WB Sport Big Country', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/bryant_reeves/warner_brothers_bc/warner_brothers_bc.jpg&w=712&h=480', 1996, 'Obscure', 'Did you know "Big Country" Bryant Reeves had a shoe? It''s a testament to his marketability coming out of college, for sure. Warner Bros. tried its hand at basketball sneakers. And they chose “Big Country” Bryant Reeves as one of their front men.', 'wb-sport-big-country') ON CONFLICT (shoe_id) DO NOTHING;
