INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (20, 18, 17, 'Puma Stewie', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/breanna_stewart/puma_stewie/puma_stewie.jpg&w=712&h=480', 2022, 'Iconic', 'Breanna Stewart is a force to be reckoned with – on and off the court. Her second signature shoe, the Stewie 2, celebrates the different areas of her life that drive her to be a force of nature. The two-time MVP told GQ in 2024 the PS3''s salute women''s hoopers who hustle from "sunrise to sunset."', 'puma-stewie') ON CONFLICT (shoe_id) DO NOTHING;
