INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (21, 4, 18, 'Adidas Ace', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/candace_parker/adidas_ace/adidas_ace.jpg&w=712&h=480', 2010, 'Standard', 'Parker’s <a href=https://andscape.com/features/candace-parker-adidas-basketball-sneakers-legacy/>Ace Commander</a>, released in 2010, was the first signature basketball sneaker <a href=https://andscape.com/features/why-la-sparks-candace-parker-has-stuck-with-adidas-her-whole-athletic-life/>Adidas made for a woman</a>. The WNBA legend’s signature line has prioritized inclusive sizing and women’s empowerment in its storytelling and has even expanded to apparel for on and off the court.', 'adidas-ace') ON CONFLICT (shoe_id) DO NOTHING;
