INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (23, 4, 20, 'Adidas C-Billups', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/chauncey_billups/adidas_c_billups/adidas_c_billups.jpg&w=712&h=480', 2007, 'Standard', 'Billups signed with Adidas in ‘04. The partnership worked so well that three years later, he signed a lifetime deal with the company.', 'adidas-c-billups') ON CONFLICT (shoe_id) DO NOTHING;
