INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (21, 1, 'Charles Barkley', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (24, 5, 21, 'Nike Air Force Max CB', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/charles_barkley/nike_air_force_max/nike_air_force_max.jpg&w=712&h=480', 1993, 'Iconic', 'During the ’90s, Charles Barkley transformed into such a tantalizing marketing tool that Nike had no choice but to give him a signature line. In commercial appearances from 1991 to 1993 alone, Barkley starred on Broadway, stood toe-to-toe with Godzilla and bluntly declared to America, “I am not a role model.” All that TV airtime spilled into his 1993 NBA MVP season, when Barkley headlined the Nike Air Force Max — which, on record, outsold the Air Jordan 8. Although Nike doesn’t officially recognize the original Air Force Max as a Barkley signature, it’s hard to deny the cultural currency Sir Charles, and even the University of Michigan’s Fab Five, delivered the shoe''s tough black, gray and white colorway. Immediately after Michael Jordan’s first NBA retirement in October 1993, Barkley became “Air Apparent” at Nike, which, by November, launched the Air Force Max CB as his first of seven official swoosh signatures.', 'nike-air-force-max-cb') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (24, 2) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
