INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (22, 1, 'Chris Webber', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (25, 19, 22, 'Dada Supreme CDubbz', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/chris_webber/dada_supreme_cdubbz/dada_supreme_cdubbz.jpg&w=712&h=480', 2002, 'Iconic', 'Chris Webber debuted the CDubbz at the 2002 NBA All-Star Game, and he took advantage of the millions of eyes watching the top players in the world. The reflective, metallic sneakers were eye-catching, but many people didn’t know that Webber was named president of fashion company Dada Damani’s basketball division less than a week before the game. Hence, he had a personal stake in making a big splash. His run at the company was short-lived but memorable.', 'dada-supreme-cdubbz') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (25, 2) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
