INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (26, 20, 22, 'FILA Webber', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/chris_webber/fila_webber/fila_webber.jpg&w=712&h=480', 1998, 'Standard', 'Webber''s only Fila signature shoe was coincidentally released on the day he was traded from the Wizards to the Kings. As conspicuous as Webber’s game was during his time with Washington, his Filas are the exact opposite. They blended in on any court with only the Fila logo making a statement.', 'fila-webber') ON CONFLICT (shoe_id) DO NOTHING;
