INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (28, 22, 24, 'Chuck Hayes Qiaodan', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/chuck_hayes/chuck_hayes_qiaodan/chuck_hayes_qiaodan.jpg&w=712&h=480', 2011, 'Standard', 'The rising tide of the Houston Rockets’ popularity in China, due to their drafting of future Hall of Famer Yao Ming, lifted his teammates into their own increased popularity individually. The tough, undersized, big man got a signature shoe out of it with the Fujijan-based brand whose name is the Chinese translation of Jordan (as in Michael).', 'chuck-hayes-qiaodan') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (114, 28, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/chuck_hayes/chuck_hayes_qiaodan/chuck_hayes_qiaodan.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (87, 28, 'Chuck Hayes Qiaodan', 2011, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/chuck_hayes/chuck_hayes_qiaodan/models/chuck_hayes_qiaodan.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
