INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (29, 5, 22, 'Nike Air Max CW', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/chris_webber/nike_air_max_cw/nike_air_max_cw.jpg&w=712&h=480', 1995, 'Iconic', 'Chris Webber’s signature Nike sneaker is like one of those cult sitcoms or dramas that get canceled just as they are finding an audience. Webber’s signature line with Nike was a one-and-done, but the sneakers'' impact continues to live on. Featuring a huge Air Max bubble at the heel, more visible air in the forefoot, and a dope logo incorporating Webber’s initials into a basketball hoop and net, it’s a travesty that we didn’t get to see Nike’s designers continue to iterate on an exceptional sneaker.', 'nike-air-max-cw') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (29, 2) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
