INSERT INTO brand (brand_id, name) VALUES (23, 'Converse') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (25, 1, 'Chuck Taylor', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (30, 23, 25, 'Converse Chuck Taylor All-Star', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/chuck_taylor/converse_chuck_taylor_all_star/converse_chuck_taylor_all_star.jpg&w=712&h=480', 1934, 'Iconic', 'The Converse Chuck Taylor is a testament to simplicity in design. The sneaker has been around for more than 100 years. Though there are high-end versions designed by brands such as the late Virgil Abloh’s Off-White or Commes De Garcon, and versions fabricated from more luxurious materials are available, the best version of the sneaker hasn’t changed much in its more than 100-year existence. Canvas upper, vulcanized rubber sole, metal eyelets, and a simple patch bearing its namesake, semiprofessional basketball player and sneaker salesman Chuck Taylor. They will never go out of style.', 'converse-chuck-taylor-all-star') ON CONFLICT (shoe_id) DO NOTHING;
