INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (34, 2, 27, 'Reebok Avant Guard', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/clyde_drexler/reebok_avant_guard/reebok_avant_guard.jpg&w=712&h=480', 1996, 'Standard', 'Reebok sold Avia in 1996, but Drexler was still under contract. As a result, he received a final Reebok sneaker — the Avant Garde — which he donned during the Houston Rockets'' championship run. The shoe''s name matched "The Glide''s" game to a tee.', 'reebok-avant-guard') ON CONFLICT (shoe_id) DO NOTHING;
