INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (30, 1, 'Clyde Frazier', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (37, 18, 30, 'Puma Clyde', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/clyde_frazier/puma_clyde/puma_clyde.jpg&w=712&h=480', 1971, 'Iconic', 'Clyde Frazier was the one of the first basketball players to have a sneaker named after him. Known as much for his colorful silk shirts, wide-brimmed fedoras and mink coats off the court as he was for his nearly unstoppable spins and hesitation moves on it, the Puma Clyde had to blend the flash of its namesake as well as perform on the court. The answer was suede and color. Suede was unusually luxurious for a performance sneaker in the ''70s and Clyde demanded that the sneaker be made from the material. Frazier also asked for a different colorway available for every game he played, which resulted in a rumored 390 shades of Clydes being produced. The sneaker exploded, was embraced by hip-hop culture — b-boys and b-girls in particular — and has remained an <a href=https://andscape.com/features/the-forgotten-history-of-puma-basketball/>all-time classic</a> for over 40 years.', 'puma-clyde') ON CONFLICT (shoe_id) DO NOTHING;
