INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (40, 5, 33, 'Nike Air Zoom S5', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/dawn_staley/nike_air_zoom_s5/nike_air_zoom_s5.jpg&w=712&h=480', 1999, 'Obscure', 'Along with NBA All-Stars like Kevin Garnett, Gary Payton and Scottie Pippen, Staley’s signature sneaker was a part of Nike’s Alpha Project. Launched in 1999, the Alpha Project was reserved for the most innovative sneakers, apparel and products. Staley’s signature kicks were no exception. With its sleek design and gold-stitched S5 logo, the legendary player and coach’s signature is one to remember.', 'nike-air-zoom-s5') ON CONFLICT (shoe_id) DO NOTHING;
