INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (35, 1, 'Dennis Rodman', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (42, 23, 35, 'Converse All-Star 91', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/dennis_rodman/converse_all_star_91/converse_all_star_91.jpg&w=712&h=480', 1997, 'Obscure', 'After a stint with Nike, the flamboyant forward signed a deal with Converse in 1997. Rodman’s initial Converse signature was the most straightforward of his sneakers with the brand — the second, wilder model, was inspired by his tattoos. Blending the soul, but not the sole, of the now century-old Chuck Taylor with modern design and Converse’s REACT Juice technology, the Converse All-Star 91 was built for the ups and downs of one of the game’s greatest rebounders.', 'converse-all-star-91') ON CONFLICT (shoe_id) DO NOTHING;
