INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (43, 5, 35, 'Nike Shake Ndestrukt', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/dennis_rodman/nike_shake/nike_shake.jpg&w=712&h=480', 1996, 'Iconic', 'It''s fitting that one of the most unusual Hall of Famers ever has one of the most unusual signature sneakers. With its asymmetrical lacing system and an shrouded upper that enveloped almost the entire shoe, the Ndestrukt was almost a metaphor for the man himself. Both had exteriors that belied the skill and creativity beneath the surface.', 'nike-shake-ndestrukt') ON CONFLICT (shoe_id) DO NOTHING;
