INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (44, 26, 36, 'BK Dymacel', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/derrick_coleman/bk_dymacel/bk_dymacel.jpg&w=712&h=480', 1992, 'Obscure', 'BK signed Derrick Coleman as lead endorser during summer 1992 and the Dyamcel Enforcer Mid released a month later for $89.99. Before DC, BK previously had deals with rappers MC Hammer and <a href=https://andscape.com/features/kool-moe-dee-and-british-knights-the-story-of-one-of-hip-hops-earliest-sneaker-campaigns/>Kool Moe Dee</a>, utilizing the slogan, "Your mother wears Nikes."', 'bk-dymacel') ON CONFLICT (shoe_id) DO NOTHING;
