INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (37, 1, 'Devin Booker', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (45, 5, 37, 'Nike Book', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/devin_booker/nike_book/nike_book.jpg&w=712&h=480', 2024, 'Standard', 'After mostly wearing shoes from Kobe Bryant’s signature line during his career, Booker received his own shoe in 2024. The Book 1 sports a clean, classic aesthetic and comes loaded with support by way of a Cushlon 2.0 foam midsole and a top-loaded Nike Zoom air bag in the heel.', 'nike-book') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (186, 45, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/devin_booker/nike_book/nike_book.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
