INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (38, 1, 'Dikembe Mutombo', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (46, 4, 38, 'Adidas Mutombo', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/dikembe_mutombo/adidas_mutombo/adidas_mutombo.jpg&w=712&h=480', 1993, 'Iconic', 'Implementing design elements inspired by Mutumbo’s home country, the Democratic Republic of the Congo, the Adidas Mutombo featured some of the most inspired design choices of any of the sneakers on this list. The late Mutombo’s jersey number figures prominently into the logo design, alongside a shield with crossed spears that nod to his African roots and reputation for defensive prowess.', 'adidas-mutombo') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (46, 2) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
