INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (39, 2, 'Diana Taurasi', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (47, 5, 39, 'NIke Air Taurasi', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/diana_taurasi/nike_air_taurasi/nike_air_taurasi.jpg&w=712&h=480', 2005, 'Standard', 'Diana Taurasi was the last WNBA player to have a Nike signature shoe before Elena Delle Donne and Sabrina Ionescu. After being drafted No. 1 in 2004, Taurasi launched her Air Max Taurasi in 2005, inspired by a Maserati. Nike later released the Shox DT in her honor. In 2021, a special edition of the LeBron 18 celebrated her heritage. Taurasi views signature sneakers as <a href=https://andscape.com/features/the-complete-history-of-signature-sneakers-in-the-wnba/>milestones in women’s sports</a> and believes players such as Ionescu set new aspirations for future generations.', 'nike-air-taurasi') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (191, 47, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/diana_taurasi/nike_air_taurasi/nike_air_taurasi.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (145, 47, 'Nike Shox DT', 2006, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/diana_taurasi/nike_air_taurasi/models/nike_shox_dt.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (192, 47, 145, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/diana_taurasi/nike_air_taurasi/models/nike_shox_dt.jpg&w=712&h=480', 'gallery') ON CONFLICT (image_id) DO NOTHING;
