INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (40, 1, 'Dwight Howard', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (48, 4, 40, 'Dwight Howard Adidas', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/dwight_howard/adidas_beast_commander/adidas_beast_commander.jpg&w=712&h=480', 2010, 'Standard', 'Howard’s signature sneaker was released during his Orlando Magic prime in 2010. The line, starting with the Beast Commander, was made with performance, and big men specifically, in mind. Adidas decked out the eight-time all-star’s signature line with some of its most advanced performance technology to support his unique combination of size and athleticism.', 'dwight-howard-adidas') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (194, 48, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/dwight_howard/adidas_beast_commander/adidas_beast_commander.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
