INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (41, 1, 'Derrick Rose', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (49, 4, 41, 'Adidas D Rose', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/derrick_rose/adidas_adizero_rose/adidas_adizero_rose.jpg&w=712&h=480', 2010, 'Standard', 'Derrick Rose’s signature line began in October 2010, during the season he won MVP. The line was created with Rose’s performance needs in mind, as one of the fastest and most athletic guards of his era. It first utilized Adidas’ ultra-light Adizero technology and went on to implement the popular Boost cushioning in later iterations.', 'adidas-d-rose') ON CONFLICT (shoe_id) DO NOTHING;
