INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (55, 21, 43, 'Jordan Fly Wade', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/dwyane_wade/jordan_fly_wade/jordan_fly_wade.jpg&w=712&h=480', 2011, 'Standard', 'After six years with Converse, Wade grew unhappy with the company. He signed with Jordan in 2010 and released his signature Jordan Fly Wade the following year.', 'jordan-fly-wade') ON CONFLICT (shoe_id) DO NOTHING;
