INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (63, 5, 50, 'Nike Air Zoom GP', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/gary_payton/nike_air_zoom_flight/nike_air_zoom_flight.jpg&w=712&h=480', 1997, 'Iconic', 'Similar to Dennis Rodman’s Nike Shake Ndestrukt (both designed by Eric Avar), a shroud feature figures prominently into the sneaker’s design. The shroud closes with a latch that allowed you to literally lock down the shoe in the same way that Payton’s lockdown defense made the mere act of crossing half court a living hell for opposing guards.', 'nike-air-zoom-gp') ON CONFLICT (shoe_id) DO NOTHING;
