INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (51, 1, 'Giannis Antetokounmpo', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (64, 5, 51, 'Nike Zoom Freak', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/giannis_antetokounmpo/nike_zoom_freak/nike_zoom_freak.jpg&w=712&h=480', 2019, 'Standard', 'Antetokounmpo’s signature sneaker line began with a <a href=https://andscape.com/features/giannis-antetokounmpo-nike-zoom-freak-5-all-star-sneakers/>wild swing from Nike</a> in design and technology. The most prominent feature is the inverted Nike Swoosh built directly into the sneaker''s heel. The second is the heel unit itself -- seemingly twice as thick as usual. The idea is to support the Greek forward’s downhill attacks, impossibly long strides and <a href=https://andscape.com/features/the-story-behind-giannis-antetokounmpos-first-nike-signature-sneaker/>nearly unstoppable Eurostep</a>; they often result in his size 16 heel striking the hardwood before he finishes plays.', 'nike-zoom-freak') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (281, 64, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/giannis_antetokounmpo/nike_zoom_freak/nike_zoom_freak.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
