INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (68, 30, 53, 'Etonic Akeem The Dream', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/hakeem_olajuwon/etonic_akeem_the_dream/etonic_akeem_the_dream.jpg&w=712&h=480', 2014, 'Obscure', 'Before signing the No. 1 pick in the 1984 NBA draft, Etonic was primarily known for making athletic shoes for professional golfers. Still, Hakeem (then known as Akeem) Olajuwon signed on with the company instead of Nike, Adidas or Converse to avoid getting lost in the glut of basketball players endorsing those other brands, becoming the face of a new entrant into the market.', 'etonic-akeem-the-dream') ON CONFLICT (shoe_id) DO NOTHING;
