INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (74, 5, 57, 'Nike Ja', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/ja_morant/nike_ja/nike_ja.jpg&w=712&h=480', 2023, 'Standard', 'In the news release announcing the release of the Ja 1 sneaker in 2023, Nike described Morant as “Nike Basketball’s first Gen Z signature athlete.” It’s clear Nike has high hopes for the hyper-athletic guard’s ability to lead the storied brand <a href=https://andscape.com/features/ja-morant-interview-nike-ja-1-sneaker/>into the future</a>, and the Nike Ja 1 is a good start.', 'nike-ja') ON CONFLICT (shoe_id) DO NOTHING;
