INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (78, 36, 61, 'New Balance Worthy Express', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/james_worthy/new_balance_worthy_express/new_balance_worthy_express.jpg&w=712&h=480', 1986, 'Obscure', 'New York-based boutique and clothing line Aimé Leon Dore has helped create a resurgence of one of New Balance’s lesser-known basketball models, the NB550. That model is actually a modification of James Worthy’s signature sneaker: the Express, also known as the P740. The Express emphasized Worthy’s speed as one of the favored recipients of fast-break dimes from Magic Johnson during the Showtime Lakers’ heyday.', 'new-balance-worthy-express') ON CONFLICT (shoe_id) DO NOTHING;
