INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (79, 5, 62, 'Nike Air Zoom Flight V', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jason_kidd/nike_air_zoom_flight_v/nike_air_zoom_flight_v.jpg&w=712&h=480', 1997, 'Iconic', 'The Nike model most closely associated with Kidd may be the Zoom Flight ‘95, which he wore during his rookie year with the Dallas Mavericks, but the Zoom Flight V was his official signature and one of the more underrated models of the era. It used the still relatively new Zoom technology, debuting on Flight ‘95. It also carried forward the bug-eyed aesthetic of that sneaker in a futuristic, reflective, metallic shape near the midsole.', 'nike-air-zoom-flight-v') ON CONFLICT (shoe_id) DO NOTHING;
