INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (68, 1, 'Joel Embiid', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (85, 16, 68, 'Under Armour Embiid One', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/joel_embiid/under_armour_embiid_one/under_armour_embiid_one.jpg&w=712&h=480', 2020, 'Standard', 'Embiid’s <a href=https://andscape.com/features/joel-embiid-skechers-basketball-sneakers/>run with Under Armour</a> was somewhat disappointing, with only one signature sneaker released during his five years with the brand. The company could never take advantage of the Philadelphia center’s outsized personality or use his one-of-a-kind game to market the sneaker in a way that made a splash to anyone besides hardcore hoops fans. Historically, sneakers for big men have been harder to market, and Embiid was a strong bet that just didn’t pan out.', 'under-armour-embiid-one') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (365, 85, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/joel_embiid/under_armour_embiid_one/under_armour_embiid_one.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
