INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (88, 37, 70, 'Karl Kani John Wallace', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/john_wallace/karl_kani_john_wallace/karl_kani_john_wallace.jpg&w=712&h=480', 1997, 'Obscure', 'Wallace, who was raised in Rochester, New York, was a four-year starter at Syracuse and was drafted by the Knicks in 1996. So, while his signing on with the New York City-based pioneering urban fashion brand Karl Kani to endorse an athletic sneaker was surprising, it also made a lot of sense.', 'karl-kani-john-wallace') ON CONFLICT (shoe_id) DO NOTHING;
