INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (89, 23, 71, 'Converse Sky Rider', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jr_rider/converse_sky_rider/converse_sky_rider.jpg&w=712&h=480', 1994, 'Standard', 'On the heels of his 1994 dunk contest win, which he confidently predicted the day he was drafted to the Minnesota Timberwolves, the uberathletic guard was outfitted in his own Converse signature.', 'converse-sky-rider') ON CONFLICT (shoe_id) DO NOTHING;
