INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (90, 23, 72, 'Converse Dr. J', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/julius_erving/converse_dr_j/converse_dr_j.jpg&w=712&h=480', 1976, 'Iconic', 'Dr. J embodied cool in the 1970s, so when <a href=https://andscape.com/features/julius-erving-rasheed-wallace-ray-allen-converse-nike-and-air-jordan-art-of-a-champion-collection/>his signature Converse sneaker</a>, the Pro Leather, launched in 1976, it immediately became the sneaker to have for hoopers and anybody who wanted to feel a fraction of the flyness Erving exuded on and off the court. The simple high-top, with quality leather and Doc’s name stamped in gold, was an instant classic.', 'converse-dr-j') ON CONFLICT (shoe_id) DO NOTHING;
