INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (94, 31, 74, 'L.A. Gear Catapult', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/karl_malone/la_gear_catapult/la_gear_catapult.jpg&w=712&h=480', 1991, 'Standard', 'The bruising power forward helped L.A. Gear briefly elbow its way into third place, behind Nike and Reebok, in the crowded, early ‘90s sneaker market.', 'la-gear-catapult') ON CONFLICT (shoe_id) DO NOTHING;
