INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (95, 36, 75, 'NB Kawhi', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/kawhi_leonard/nb_kawhi/nb_kawhi.jpg&w=712&h=480', 2020, 'Standard', 'In 2018, New Balance made a surprising reentry into the basketball category by signing Leonard, who made an equally surprising move by leaving Jordan behind for the company most often associated with running sneakers. With multiple iterations under their belt, the partnership looks great in hindsight as NB continues to grow its footprint in hoops.', 'nb-kawhi') ON CONFLICT (shoe_id) DO NOTHING;
