INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (97, 4, 77, 'Adidas Garnett', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/kevin_garnett/adidas_garnett/adidas_garnett.jpg&w=712&h=480', 2004, 'Standard', 'KG’s Nike models might have had the bigger impact on sneaker culture in the late ''90s and early ''00s, but he had the most success while wearing Adidas. He won his only MVP award with the Timberwolves and a pair of Larry O’Brien trophies with the Celtics wearing the Three Stripes.', 'adidas-garnett') ON CONFLICT (shoe_id) DO NOTHING;
