INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (100, 5, 77, 'Nike Air Garnett', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/kevin_garnett/nike_air_garnett/nike_air_garnett.jpg&w=712&h=480', 1998, 'Standard', 'Garnett repped several different sneaker brands throughout his career, but his first signature came with Nike. Only three models were produced before he switched to Nike’s Flightposite line, but they were memorable, with the Air Garnett III being the most remembered among them.', 'nike-air-garnett') ON CONFLICT (shoe_id) DO NOTHING;
