INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (102, 3, 79, '361 Kevin Love', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/kevin_love/361_kevin_love/361_kevin_love.jpg&w=712&h=480', 2011, 'Standard', 'Chinese shoe brand 361 Degrees takes its name from the additional 1 degree of intensity after completing a 360-degree circle, which it describes as “that extra push, that added intensity.” Love became known as a complementary stretch 4 later in his career during his championship runs with LeBron James’ Cavs. Still, when he initially signed with 361 Degrees, he was a bruising double-double-machine power forward who embodied the brand’s ethos.', '361-kevin-love') ON CONFLICT (shoe_id) DO NOTHING;
