INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (103, 4, 80, 'Adidas KB8', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/kobe_bryant/adidas_kb8/adidas_kb8.jpg&w=712&h=480', 1997, 'Standard', 'Before joining Nike, Bryant spent his <a href=https://andscape.com/features/kobe-bryants-story-through-signature-sneaker-moments/>early seasons with Adidas</a>. The polarizing Kobe 2 still looks as unusual today as it did in 2001.', 'adidas-kb8') ON CONFLICT (shoe_id) DO NOTHING;
