INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (82, 1, 'Kevin Durant', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (105, 5, 82, 'Nike KD', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/kevin_durant/nike_kd/nike_kd.jpg&w=712&h=480', 2009, 'Standard', 'Kevin Durant is one of the most consistent scorers ever. He can get to whatever spots he wants, rise up with his elbow at a protractor-perfect angle and knock down any shot -- in open space or while smothered by good defense. It was important that his signature sneaker perform night in and night out, just like him. The KD signature line is consistently among the better performance sneakers on the market. What’s different, though, is that it also features some of the most sought-after sneakers for off-the-court wear. Certain colorways of the fourth, fifth and sixth iterations of the Nike KDs can resell for more than $1,000.', 'nike-kd') ON CONFLICT (shoe_id) DO NOTHING;
