INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (108, 18, 84, 'Puma MB', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/lamelo_ball/puma_mb/puma_mb.jpg&w=712&h=480', 2021, 'Standard', 'LaMelo Ball had one of the most unusual paths to the NBA of any All-Star-caliber player, including stints at two high schools, playing in the short-lived Junior Basketball Association, and two seasons of pro ball in Lithuania and Australia, all before turning 18. The same was true of his basketball sneaker history, as he infamously had a signature sneaker in high school as a part of his family’s Big Baller Brand. Finally, just before being drafted by the Charlotte Hornets, Ball signed a deal for a purported $100 million to lace up a <a href=https://andscape.com/features/lamelo-ball-puma-mb02-interview/>new signature line by Puma</a>.', 'puma-mb') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (479, 108, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/lamelo_ball/puma_mb/puma_mb.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
