INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (109, 5, 80, 'Nike Kobe', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/kobe_bryant/nike_kobe/nike_kobe.jpg&w=712&h=480', 2001, 'Iconic', 'To get a sense of how popular the <a href=https://andscape.com/features/how-the-nba-has-mourned-kobe-bryant-through-sneakers/>late Kobe Bryant’s</a> sneakers are among NBA basketball players, think back to the year following Kobe’s tragic death. From April 2020 to April 2021, 45% of all NBA players <a href=https://andscape.com/features/the-staggering-popularity-of-kobe-bryants-nike-signature-series-this-nba-season/>wore Kobe’s signature shoe</a> at least one time. Even Nike’s most recent signature lines with Devin Booker and Ja Morant appear to draw inspiration from Bryant’s. The <a href=https://andscape.com/features/the-kobe-5-behind-the-biggest-sneaker-tribute-in-basketball/>most popular models</a> of Kobes repopularized the low-cut hoop sneaker, making it the style of choice of basically every ballplayer under 35 to this day. After a brief impasse with Bryant’s estate and pairs of Kobes becoming extremely scarce for a couple of years, the line lives on and thrives like the memory of the Black Mamba, a player whose name is associated with excellence, hard work and a steely competitive drive unseen in almost any other player not named Michael Jordan.', 'nike-kobe') ON CONFLICT (shoe_id) DO NOTHING;
