INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (111, 5, 83, 'Nike Kyrie', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/kyrie_irving/nike_kyrie/nike_kyrie.jpg&w=712&h=480', 2014, 'Iconic', 'There was a seven-year drought of new Nike signature basketball sneakers before the Kyrie dropped in 2014. The ubertalented guard’s line quickly became a favorite among fellow NBA players and hoopers worldwide. Irving released nine signature shoes with Nike and the line was perhaps the best blend of performance and style since KD.', 'nike-kyrie') ON CONFLICT (shoe_id) DO NOTHING;
