INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (113, 23, 86, 'Black White Converse Weapon', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/larry_bird/black_white_converse_weapon/black_white_converse_weapon.jpg&w=712&h=480', 1986, 'Iconic', 'Bird debuted his black-and-white Converse Weapons during the inaugural NBA 3-point contest in 1986, where he famously asked his competitors in the locker room who they thought would come in second place. Playing up the rivalry between him and Magic Johnson, Converse launched its “Choose Your Weapon” marketing campaign in the same year Bird won his third and final NBA championship.', 'black-white-converse-weapon') ON CONFLICT (shoe_id) DO NOTHING;
