INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (117, 43, 87, 'Dada Supreme Sprewell Spinners', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/latrell_sprewell/dada_sprewell_spinners/dada_sprewell_spinners.jpg&w=712&h=480', 2003, 'Iconic', 'You had to be there to understand, but custom automobile rims were a thing in the late ''90s through the early 2000s. Every year, they seemed to get bigger, with heights climbing over 2 feet. In an unusual twist, talented shooting guard Latrell Sprewell was also the owner of a car customization shop that helped popularize “spinners” — rims with a second face that would keep spinning after the car had stopped. When he began to endorse upstart fashion brand DaDa’s foray into performance footwear, the company smartly integrated the spinner design into the athletic wing’s signature sneaker.', 'dada-supreme-sprewell-spinners') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (117, 2) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
