INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (119, 5, 90, 'Nike Air Leslie', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/lisa_leslie/nike_total_air/nike_total_air.jpg&w=712&h=480', 1998, 'Iconic', 'Unfortunately, Lisa Leslie’s Nike Air Total 9 was her only signature, but it was a memorable one. The former Wilhelmina model and all-time leading WNBA scorer and rebounder''s sneaker was inspired by the quilted leather of Chanel handbags.', 'nike-air-leslie') ON CONFLICT (shoe_id) DO NOTHING;
