INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (94, 1, 'Luka Doncic', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (123, 21, 94, 'Jordan Luka', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/luka_doncic/jordan_luka/jordan_luka.jpg&w=712&h=480', 2022, 'Standard', 'The original 1997 class of Jordan Brand basketball players consisted of a handful of young stars on the rise, one of whom ended up a Hall of Famer (Ray Allen). It’s way too early to say at this point, but it feels very likely that the new class of Jordan Brand reps will include at least one player with a Hall of Fame career -- Slovenian hardwood magician Luka Doncic. His signature line features some of Jordan Brand’s most innovative technology, including Formula 23 foam, which makes it extremely lightweight, and IsoPlate in the footbed for stability.', 'jordan-luka') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (560, 123, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/luka_doncic/jordan_luka/jordan_luka.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
