INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (124, 23, 95, 'Converse Magic Johnson', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/magic_johnson/purple_gold_converse_weapon/purple_gold_converse_weapon.jpg&w=712&h=480', 1986, 'Iconic', 'Starting with the 1979 NCAA championship between Michigan State and Indiana State, the careers of Magic Johnson and Larry Bird have been forever intertwined. Launched at the 1986 NBA All-Star Game, a year Johnson’s Lakers were defending their NBA title, Magic received his signature sneaker, the high-top Converse Weapon in Lakers purple and gold.', 'converse-magic-johnson') ON CONFLICT (shoe_id) DO NOTHING;
