INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (126, 6, 96, 'Peak Delly', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/matthew_dellavedova/peak_delly/peak_delly.jpg&w=712&h=480', 2017, 'Standard', 'Dellavedova is a NBA champ, an Olympian and the first Australian NBA player in the modern era with his own sig shoe.', 'peak-delly') ON CONFLICT (shoe_id) DO NOTHING;
