INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (127, 9, 97, 'AND1 ME8 Empire Mid', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/monta_ellis/and1_me8_empire_mid/and1_me8_empire_mid.jpg&w=712&h=480', 2011, 'Standard', 'It makes sense Ellis and AND1 worked together on shoes. His game had the flair of an AND1 legend. These in particular came during the lockout-stressed days of 2011.', 'and1-me8-empire-mid') ON CONFLICT (shoe_id) DO NOTHING;
