INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (128, 20, 98, 'Fila Nikki Delta', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/nikki_mccray/fila_nikki_delta/fila_nikki_delta.jpg&w=712&h=480', 1999, 'Standard', 'Once she left Converse in 1998, the late, great McCray-Penson linked up with Fila and gave the world these sneakers.', 'fila-nikki-delta') ON CONFLICT (shoe_id) DO NOTHING;
