INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (99, 1, 'Patrick Ewing', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (129, 4, 99, 'Adidas Attitude Hi', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/patrick_ewing/adidas_attitude_hi/adidas_attitude_hi.jpg&w=712&h=480', 1986, 'Iconic', 'Ewing laced up the Three Stripes before starting his eponymous line. The rugged Attitude Hi was the perfect encapsulation of Knicks basketball and Ewing’s DNA as a former Georgetown Hoya, a college team that struck fear into the hearts of its opponents with its swarming defense and aggressive play. With its high collar, thick midsole and minimal branding, the Attitude was a sneaker built for work. The Attitude also fits well on the streets of NYC, with its iconic blue and orange colorway reminiscent of the hometown Knicks and Mets.', 'adidas-attitude-hi') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (129, 2) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
