INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (130, 45, 99, 'Patrick Ewing Basketball Shoe', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/patrick_ewing/patrick_ewing_basketball_shoe/patrick_ewing_basketball_shoe.jpg&w=712&h=480', 1990, 'Standard', 'The Knicks Hall of Famer launched his own brand and signature sneaker in 1989 after parting with Adidas. The most recognizable model, the 33 Hi, is still in production today.', 'patrick-ewing-basketball-shoe') ON CONFLICT (shoe_id) DO NOTHING;
