INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (131, 5, 100, 'Nike PG', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/paul_george/nike_pg/nike_pg.jpg&w=712&h=480', 2017, 'Standard', 'George''s signature series ran for six models before meeting its end. Affordability, great color stories and solid technology were hallmarks for a line favored by players and fans alike. Nike collaborated with Sony for multiple PlayStation-inspired versions that were well received.', 'nike-pg') ON CONFLICT (shoe_id) DO NOTHING;
