INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (133, 5, 102, 'Nike LeBron', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/lebron_james/nike_lebron/nike_lebron.jpg&w=712&h=480', 2003, 'Iconic', 'Before he played a single NBA game, Nike paid LeBron James $90 million to <a href=https://andscape.com/features/lebron-james-rookie-sneaker-deal-nike-adidas-reebok/>endorse its sneakers</a>. Coming to the NBA straight out of high school was a difficult burden to live up to, and he had more than a few people hoping to see him fall flat on his face. Twenty-one NBA seasons, 56,598 total minutes played, four NBA championships, three gold medals, and, including his recently announced training sneaker, the LeBron TR1, twenty-two models of the Nike LeBron later, the kid from Akron, Ohio, continues, improbably, to evade Father Time and play basketball at an All-NBA level by keeping his head down and putting one shoe in front of the other.', 'nike-lebron') ON CONFLICT (shoe_id) DO NOTHING;
