INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (103, 1, 'Penny Hardaway', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (134, 5, 103, 'Nike Air Penny', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/penny_hardaway/nike_air_penny/nike_air_penny.jpg&w=712&h=480', 1995, 'Iconic', 'Despite a career shortened by injuries, Penny Hardaway was a <a href=https://andscape.com/features/penny-hardaway-on-the-time-michael-jordan-wore-air-flight-ones-over-his-own-concord-11s/>hugely influential basketball player</a>. His blend of court vision and athleticism was a basketball fever dream — a hybrid of Magic Johnson and Michael Jordan. His signature sneaker line, outfitted in the royal blue colorway made for his prime years with the Orlando Magic, is among the most revered by sneakerheads. And if you throw in “unofficial” signatures like the Foamposite and the Air Go LWP, among others, his line is in the conversation for the best ever.', 'nike-air-penny') ON CONFLICT (shoe_id) DO NOTHING;
