INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (135, 23, 104, 'Converse No Limit MP', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/percy_miller/converse_no_limit_mp/converse_no_limit_mp.jpg&w=712&h=480', 1999, 'Obscure', 'A short stint in the now defunct Continental Basketball Association and even briefer stints on the training camp rosters of the NBA’s Charlotte Hornets and Toronto Raptors aren’t typically enough for most players to get a signature sneaker. But most players aren’t Grammy Award-winning rapper and millionaire businessman Master P.', 'converse-no-limit-mp') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (135, 1) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
