INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (509, 135, 'Converse No Limit MP', 1999, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/percy_miller/converse_no_limit_mp/models/converse_no_limit_mp.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (644, 135, 509, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/percy_miller/converse_no_limit_mp/models/converse_no_limit_mp.jpg&w=712&h=480', 'gallery') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (105, 1, 'Michael Jordan', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (136, 5, 105, 'Air Jordan', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/michael_jordan/air_jordan/air_jordan.jpg&w=712&h=480', 1984, 'Iconic', 'This sneaker is an <a href=https://andscape.com/features/howard-h-white-jordan-brand-interview/>inflection point</a>. There has never been, before or since, a convergence of innovation in design, creativity in marketing, excellence in athletic performance, and <a href=https://andscape.com/features/air-movie-true-to-nike-chase-of-michael-jordan/>cultural impact</a> in one product like the Air Jordan. In its nearly 40-year history, the line has included contributions from Oscar winner Spike Lee, International Design Award recipient Tinker Hatfield, several Clio award-winning creatives, and, oh yeah, the <a href=https://andscape.com/features/behind-the-iconic-moments-when-michael-jordan-wore-the-bred-air-jordan-11s/>GOAT</a>. That said, the most important contribution to the <a href=https://andscape.com/features/on-his-60th-birthday-23-little-known-sneaker-stories-about-michael-jordan/>success of the Air Jordan</a> didn’t happen in design studios, commercial sets, boardrooms, or even on basketball courts. It happened on subway platforms, school hallways and street corners. Nike and Jordan Brand made the sneakers popular, but regular people made them iconic.', 'air-jordan') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (136, 2) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
