INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (137, 18, 106, 'Puma Majesty Ralph Sampson', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/ralph_sampson/puma_majesty_ralph_sampson/puma_majesty_ralph_sampson.jpg&w=712&h=480', 1984, 'Iconic', 'Ralph Sampson was an early precursor to the tall, wiry, athletic players like Chet Holmgren and Victor Wembenyama who are galloping through the present-day NBA. The Majesty was made to the specifications of Sampson, whose height, length and ballhandling ability at his size were unique at the time.', 'puma-majesty-ralph-sampson') ON CONFLICT (shoe_id) DO NOTHING;
