INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (138, 2, 107, 'Reebok Lobo', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/rebecca_lobo/reebok_lobo/reebok_lobo.jpg&w=712&h=480', 1997, 'Iconic', 'One of the marquee players who helped launch the WNBA in the late ''90s, Lobo was the among the first women to receive a signature basketball sneaker with Reebok. The former Connecticut Husky center debuted her Reebok Lobo in 1997 as a member of the New York Liberty. The sneaker included the Hexalite technology that Reebok featured prominently on all of its basketball sneakers of the era.', 'reebok-lobo') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (138, 2) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
