INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (139, 46, 108, 'BALL''N Layup', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/ron_artest_metta_world_peace/balln_layup/balln_layup.jpg&w=712&h=480', 2009, 'Standard', 'Few players have worn a wider array of signature sneakers as Metta Sandiford-Artest. BALL’N was a short-lived brand that produced a completely inoffensive high-top and low-top version of their Layup model, which Artest wore for a year during a stint with the Lakers.', 'balln-layup') ON CONFLICT (shoe_id) DO NOTHING;
