INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (140, 32, 109, 'Anta RR', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/rajon_rondo/anta_rr/anta_rr.jpg&w=712&h=480', 2014, 'Standard', 'Two years after connecting with Anta, Rajon Rondo launched his signature model. The RR1 and subsequent models had a good reputation as performance shoes but didn’t make a huge impact on sneaker culture.', 'anta-rr') ON CONFLICT (shoe_id) DO NOTHING;
