INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (145, 1, 108, 'Protege Signature', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/ron_artest_metta_world_peace/protege_signature/protege_signature.jpg&w=712&h=480', 2006, 'Standard', 'Created by fellow NBA player Al Harrington in the late 2000s, Protege was marketed as a low-cost alternative to Nike, Adidas and Reebok. Unlike Artest’s other signature models, the Protege took more design risks, including a huge Velcro strap across the eyelets and some eye-popping colorways.', 'protege-signature') ON CONFLICT (shoe_id) DO NOTHING;
