INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (110, 2, 'Sabrina Ionescu', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (146, 5, 110, 'Nike Sabrina', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/sabrina_ionescu/nike_air_sabrina/nike_air_sabrina.jpg&w=712&h=480', 2023, 'Standard', 'According to Nike, in 2023 Ionescu became the first women’s basketball player to release a unisex signature shoe. The Air Sabrina shares some DNA with the beloved Kobe Bryant signature line. And not unlike Bryant''s revolutionary sneaker, Ionescu’s signature has become extremely popular among her fellow pro hoopers in both the NBA and the W.', 'nike-sabrina') ON CONFLICT (shoe_id) DO NOTHING;
