INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (147, 2, 111, 'Reebok The Dime', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/saudia_roundtree/reebok_the_dime/reebok_the_dime.jpg&w=712&h=480', 1997, 'Iconic', 'Former junior college player of the year, SEC player of the year and 1997 ESPY Award winner for Best Female College Basketball Player, Saudia Roundtree signed a contract with Reebok before joining the short-lived American Basketball League. Roundtree’s midcut sneaker was called The Dime as a reference to her jersey number and her ability to turn on one.', 'reebok-the-dime') ON CONFLICT (shoe_id) DO NOTHING;
