INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (151, 5, 115, 'Nike Air Pippen', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/scottie_pippen/nike_air_pippen/nike_air_pippen.jpg&w=712&h=480', 1996, 'Iconic', 'A terror in transition and a playmaker par excellence, Scottie Pippen was a key reason why the ''90s Chicago Bulls were one of the most unstoppable forces in sports history. Even though he was the second-best player on his team, his game was so highlight-reel-worthy that he earned his own Nike signature sneaker line. This was not a case of Bulls'' brotherhood nepotism. Pippen was a star in his own right, and his sneaker line reflected it. There were some seriously memorable designs, especially the jewel zigzags of the Air Pippen I and the understated sophistication of the II.', 'nike-air-pippen') ON CONFLICT (shoe_id) DO NOTHING;
