INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (153, 2, 116, 'Reebok Shaq', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/shaquille_oneal/reebok_shaq_attaq/reebok_shaq_attaq.jpg&w=712&h=480', 1993, 'Iconic', 'It’s hard to overstate how popular Shaq was coming out of LSU into the NBA and how important it was for Reebok to get his signature sneaker right. The Shaq Attaq was a phenomenon. With its bulbous ankle collar and Pump technology, the original Shaq Attaq sneaker single-handedly lifted Reebok’s fortunes in the basketball space and helped make it a real player. The commercial promoting its release featured legendary big men Wilt Chamberlain, Bill Russell, Bill Walton and Kareem Abdul-Jabbar, effectively passing Shaq the torch as the next in their lineage. Subsequent models in the line never quite lived up to the hype of the Shaq Attaq I, which was an absolute game changer.', 'reebok-shaq') ON CONFLICT (shoe_id) DO NOTHING;
