INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (155, 2, 117, 'Reebok Shawn Kemp', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/shawn_kemp/reebok_kamikaze/reebok_kamikaze.jpg&w=712&h=480', 1994, 'Iconic', 'Reebok’s had its fair share of memorable signature athletes on its roster, but few flew higher than Shawn Kemp. In the ''90s, the Seattle Supersonics power forward terrorized opponents with thundering dunks and prowled the lane on D, swatting shots with ferocity. And he did it wearing his signature kicks -- most memorably, the Kamikaze I and II. The triangular patterns and contrasting colors to match the Supersonics unis made an eye-catching sight meant to match the Reignman’s electric play.', 'reebok-shawn-kemp') ON CONFLICT (shoe_id) DO NOTHING;
