INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (119, 2, 'Sheryl Swoopes', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (157, 5, 119, 'Nike Air Swoopes', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/sheryl_swoopes/nike_air_swoopes/nike_air_swoopes.jpg&w=712&h=480', 1995, 'Iconic', 'There is no <a href=https://andscape.com/features/aja-wilson-nike-signature-shoe-deal/>A’ja Wilson</a> or Caitlin Clark without Sheryl Swoopes. The three-time WNBA MVP and four-time WNBA champion is one of the greatest basketball players of all time and was a bona fide superstar of the burgeoning women’s league.. The Air Swoopes line was a flashpoint in basketball history and a precursor to the current popularity of not only the WNBA as a league but its players as individuals with personalities. First, the sneaker solved a simple, practical problem: women’s basketball players no longer had to buy men’s shoes in smaller sizes just to hoop. Secondly, even though the sneaker was made with women athletes in mind, veteran designer Marni Gerber’s vision for the Air Swoopes eschewed the “shrink it and pink it” aesthetic that too frequently permeated women’s athletic wear. Swoopes was a hard-nosed, relentless attacker with the ball and her sneakers needed to help her perform. Its adjustable strap and heel tab loop for ease of pulling on the sneakers with a full set of nails made the Air Swoopes I an instant classic and set a path for the line to continue until 2001.', 'nike-air-swoopes') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (157, 2) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
