INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (159, 51, 120, 'Curry Flow', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/stephen_curry/curry_flow/curry_flow.jpg&w=712&h=480', 2020, 'Standard', 'The Curry Flow is the first sneaker under the Curry Brand umbrella and uses its own unique technology. The Flow cushioning platform eschews rubber completely and is all foam. Curry says the Flow technology makes the sneaker grippier underfoot and provides excellent cushioning. The peerless shooter won his fourth championship in the Curry Flow 9s.', 'curry-flow') ON CONFLICT (shoe_id) DO NOTHING;
