INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (161, 16, 120, 'UA Curry', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/stephen_curry/ua_curry/ua_curry.jpg&w=712&h=480', 2014, 'Standard', 'After a few injury-plagued seasons to start his career, Curry began to break out in 2012, becoming an NBA All-Star. A few years later, the deep shooting guard signed a <a href=https://andscape.com/features/stephen-curry-reflects-on-his-signature-sneakers/>contract with Under Armour</a> that resulted in him becoming the undisputed face of the brand, and his eponymous line where other fellow athletes like DeAaron Fox can now play wearing Curry Brand sneakers.', 'ua-curry') ON CONFLICT (shoe_id) DO NOTHING;
