INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (162, 2, 122, 'Reebok Winx DMX', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/steve_francis/reebok_winx_dmx/reebok_winx_dmx.jpg&w=712&h=480', 2001, 'Standard', 'Draw their moniker from Francis'' childhood nickname, the Reebok Wink is an underrated shoe for an equally underrated point guard who captivated fans for years in the early aughts.', 'reebok-winx-dmx') ON CONFLICT (shoe_id) DO NOTHING;
