INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (169, 21, 128, 'Jordan Jumpman Pro Strong', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/vin_baker/jordan_jumpman_pro_strong/jordan_jumpman_pro_strong.jpg&w=712&h=480', 1998, 'Standard', 'Vin Baker was the lone big man to be a member of the original cohort of Jordan Brand athletes known as Team Jordan. He and Eddie Jones were the only players to get signature shoes out of the deal.', 'jordan-jumpman-pro-strong') ON CONFLICT (shoe_id) DO NOTHING;
