INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (171, 4, 130, 'Adidas TMAC', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/tracy_mcgrady/adidas_tmac/adidas_tmac.jpg&w=712&h=480', 2001, 'Iconic', 'The T-Mac line remains hugely popular in China. In addition to being one of the most talented players of his era, McGrady teamed with Yao Ming during his prime. The duo formed what was easily the most popular NBA team in China, with fans staying up at ungodly hours just to catch a glimpse of their countryman and T-Mac during their respective peaks.', 'adidas-tmac') ON CONFLICT (shoe_id) DO NOTHING;
