INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (172, 18, 131, 'Puma Vinsanity', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/vince_carter/puma_vinsanity/puma_vinsanity.jpg&w=712&h=480', 1999, 'Obscure', 'An unusual footnote in signature sneaker history, the Puma Vinsanity was never released to the public. Puma signed Carter as a rookie but terminated the contract a year and a half later, ultimately landing both parties in arbitration.', 'puma-vinsanity') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (172, 1) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
