INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (173, 5, 131, 'Nike Shox VC', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/vince_carter/nike_shox_vc/nike_shox_vc.jpg&w=712&h=480', 2000, 'Iconic', 'Carter jumped over 7-foot-2 Frederic Weis in these sneakers. We can talk about the long-developed Shox technology that Nike unveiled on the BB4 in 2000. We can talk about the exposed heel unit or the design inspiration that came from NASA. But nothing more important can be said about the impact of this sneaker than the fact that they were worn during perhaps the most incredible in-game dunk of all time.', 'nike-shox-vc') ON CONFLICT (shoe_id) DO NOTHING;
