INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (134, 1, 'Yao Ming', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (177, 2, 134, 'Reebok High Post', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/yao_ming/reebok_high_post/reebok_high_post.jpg&w=712&h=480', 2004, 'Obscure', 'To start his career, Yao was a Nike athlete, but the brand neglected to renew his contract, opening the door for him to join Reebok. He wore some pretty interesting player exclusives during his time with Reebok, including perhaps the largest Iverson Question ever produced (size 20), but ultimately received his own signature, the High Post. The model featured an oversized Reebok logo, which mirrored how much bigger the 7-foot-5 Yao was than his competition.', 'reebok-high-post') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (177, 1) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
