INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (135, 1, 'Zion Williamson', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (178, 21, 135, 'Jordan Zion', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/zion_williamson/jordan_zion/jordan_zion.jpg&w=712&h=480', 2021, 'Standard', 'Through its first three iterations, <a href=https://andscape.com/features/zion-williamson-journey-with-the-jordan-brand-to-the-zion-1/>Zion’s signature line</a> has seen quite a bit of variation, from the super light and sleek silhouette of the Zion 1 to the sturdy lockdown and forefoot strap of the Zion 2 to the Zion 3 that seems to split the difference. If you’re a fan of the Zion line, expect the unexpected.', 'jordan-zion') ON CONFLICT (shoe_id) DO NOTHING;
