INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (179, 13, 136, 'PONY Uptown', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/darryl_dawkins/pony_uptown/pony_uptown.jpg&w=712&h=480', 1984, 'Standard', 'Dawkins infamously switched out of his Nike sneakers for a pair of Ponys while he was still under contract with the Beaverton behemoth in the middle of a playoff game. Nike sued Dawkins and Chocolate Thunder later officially signed on with Pony.', 'pony-uptown') ON CONFLICT (shoe_id) DO NOTHING;
