INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (180, 55, 137, 'Brooks Unique', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/dominique_wilkins/brooks_unique/brooks_unique.jpg&w=712&h=480', 1983, 'Standard', 'Brooks never quite took off in the basketball space, but Nique took flight in these bold high-tops, winning two NBA dunk contests in them.', 'brooks-unique') ON CONFLICT (shoe_id) DO NOTHING;
