INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (139, 1, 'Spud Webb', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (182, 13, 139, 'Pony City Wings', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/spud_webb/pony_city_wings/pony_city_wings.jpg&w=712&h=480', 1985, 'Standard', 'In the ‘80s, the term high-tops became synonymous with basketball, and low-top basketball sneakers had fallen out of favor. Spud Webb bucked the trend and made this low-top model famous during his high-flying win over teammate Dominique Wilkins in the 1986 NBA dunk contest.', 'pony-city-wings') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (871, 182, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/spud_webb/pony_city_wings/pony_city_wings.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
