INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (140, 1, 'Lloyd Daniels', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (183, 26, 140, 'British Knights Vengeance', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/lloyd_daniels/british_knights_vengeance/british_knights_vengeance.jpg&w=712&h=480', 1993, 'Standard', 'There was a brief trend in the early ''90s of sneakers made specifically for outdoor play — most notably, the Reebok Blacktop line. So it’s no surprise that streetball-legend-turned-pro “Sweet Pea” Daniels’ signature sneaker was made with the asphalt in mind.', 'british-knights-vengeance') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (873, 183, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/lloyd_daniels/british_knights_vengeance/british_knights_vengeance.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
