INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (141, 1, 'Luke Walton', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (184, 31, 141, 'L.A. Gear Catapult Crossover', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/luke_walton/la_gear_catapult_crossover/la_gear_catapult_crossover.jpg&w=712&h=480', 2003, 'Standard', 'It’s rare that rookies receive a signature sneaker, especially those selected in the second round, but L.A. Gear took a chance on Walton during a brand relaunch in 2003. The sneaker’s Catapult tech claimed to redirect impact and propel the wearer.', 'la-gear-catapult-crossover') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (875, 184, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/luke_walton/la_gear_catapult_crossover/la_gear_catapult_crossover.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
