INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (185, 13, 142, 'Pony Inspiration', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/laphonso_ellis/pony_inspiration/pony_inspiration.jpg&w=712&h=480', 1985, 'Standard', 'The athletic power forward was drafted the same year as Shaquille O’Neal and Alonzo Mourning, but still managed to make a big enough splash to earn his own sneaker.', 'pony-inspiration') ON CONFLICT (shoe_id) DO NOTHING;
