INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (186, 57, 143, 'Asics Gel-Spotlyte', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/isiah_thomas/asics_gel_spotlyte/asics_gel_spotlyte.jpg&w=712&h=480', 1990, 'Standard', 'Better known in the running space, Asics produced a basketball sneaker made of lighter materials with a lower profile for one of the fastest guards ever.', 'asics-gel-spotlyte') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (879, 186, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/isiah_thomas/asics_gel_spotlyte/asics_gel_spotlyte.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
