INSERT INTO brand (brand_id, name) VALUES (58, 'Osaga') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (144, 1, 'John Salley', false) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (187, 58, 144, 'Osaga Spider', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/john_salley/osaga_spider/osaga_spider.jpg&w=712&h=480', 1990, 'Standard', 'Osaga was originally a running shoe brand that started in Oregon in the 1970s. Sound familiar? Salley earned the nickname Spider for his long limbs that made him a menace on defense. His signature sneaker took on the same moniker.', 'osaga-spider') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (881, 187, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/john_salley/osaga_spider/osaga_spider.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
