INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (882, 187, 695, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/john_salley/osaga_spider/models/osaga_spider.jpg&w=712&h=480', 'gallery') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (188, 6, 62, 'Jason Kidd Peak', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jason_kidd/jason_kidd_peak/jason_kidd_peak.jpg&w=712&h=480', 2008, 'Standard', 'Kidd wore Nike during his rookie run with the Dallas Mavericks. He returned to the Mavs during the twilight of his career as a crafty veteran contributor who had a lot left in the tank, even though his years as the fastest with the ball in the NBA were long behind him. He won his only NBA championship against the favored LeBron James-led Miami Heat, wearing his Peak signature in 2011.', 'jason-kidd-peak') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (883, 188, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jason_kidd/jason_kidd_peak/jason_kidd_peak.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (696, 188, 'Jason Kidd Peak', 2008, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jason_kidd/jason_kidd_peak/models/jason_kidd_peak.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (884, 188, 696, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jason_kidd/jason_kidd_peak/models/jason_kidd_peak.jpg&w=712&h=480', 'gallery') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (189, 18, 143, 'Puma Palace Guard', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/isiah_thomas/puma_palace_guard/puma_palace_guard.jpg&w=712&h=480', 1989, 'Standard', 'Isiah Thomas, known for his fearless play on the court, made a risky career move in 1989. He left Converse, his longtime sponsor, to sign with Puma. The gamble paid off when he dominated the 1990 NBA Finals, earning the MVP award while sporting his new signature shoe, the Puma Palace Guard.', 'puma-palace-guard') ON CONFLICT (shoe_id) DO NOTHING;
