INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (145, 1, 'De''Aaron Fox', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (190, 51, 145, 'Curry Fox', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/deaaron_fox/curry_fox/curry_fox.jpg&w=712&h=480', 2024, 'Standard', 'Sacramento Kings All-Star guard De’Aaron Fox made history with his debut signature shoe, which he landed under Curry Brand, the footwear and apparel subsidiary of Under Armour led by Golden State Warriors star Stephen Curry. Released on Dec. 6, 2024, the Curry Fox 1 marked the first time in NBA history that a signature model featured the names of two active players. “The opportunity to receive a shoe with both my and Steph’s names is dope,” Fox told Andscape. “From a business standpoint, I thought it was a great opportunity.” After being hand-picked as the Curry Brand’s first-ever signature athlete, Fox had three requests for his debut performance sneaker. He wanted a low top; he wanted it to feel like a running shoe; and he wanted a strap. The Curry Fox 1 delivered on all those design cues, highlighted by a midfoot strap resembling a fox’s tail.', 'curry-fox') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (887, 190, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/deaaron_fox/curry_fox/curry_fox.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (698, 190, 'Curry Fox 1', 2024, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/deaaron_fox/curry_fox/models/curry_fox_1.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (888, 190, 698, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/deaaron_fox/curry_fox/models/curry_fox_1.jpg&w=712&h=480', 'gallery') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (146, 1, 'Nikola Jokic', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (191, 3, 146, '361 Joker', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/nikola_jokic/361_joker/361_joker.jpg&w=712&h=480', 2024, 'Standard', 'A signature shoe is inevitable for certain NBA players. That was the case for Denver Nuggets star Nikola Jokic — an NBA champion and three-time league MVP — who received his first-ever signature model 10 seasons into his career. In late 2023, “The Joker” landed a signature endorsement deal from the Chinese brand 361, which signed the 6-foot-11 playmaking center thanks to the help of Aaron Gordon, Jokic’s longtime Nuggets teammate who, in 2020, became a signature headliner for 361. Jokic joined Gordon and Dallas Mavericks guard Spencer Dinwiddie as the third active player in the NBA with a 361 signature shoe. Unveiled on Dec. 3, 2024, the Joker 1 features a sleek design, highlighted by a detailed, jester-themed signature logo. Released in the United States, China and his hometown of Belgrade, Serbia, Jokic’s debut shoe further extended his platform as a global phenomenon.', '361-joker') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (889, 191, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/nikola_jokic/361_joker/361_joker.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (699, 191, '361 Joker 1', 2024, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/nikola_jokic/361_joker/models/361_joker_1.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (890, 191, 699, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/nikola_jokic/361_joker/models/361_joker_1.jpg&w=712&h=480', 'gallery') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (147, 1, 'Shai Gilgeous-Alexander', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (192, 23, 147, 'Converse SHAI', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/shai_gilgeous-alexander/converse_shai/converse_shai.jpg&w=712&h=480', 2025, 'Standard', 'In 2020, Converse and Shai Gilgeous-Alexander took a chance on each other, as basketball’s oldest footwear brand sought a return to relevancy with the Oklahoma City Thunder’s rising star point guard. The partnership proved to be a perfect match, with SGA transforming into an All-NBA talent and off-court style icon as the league’s face of Converse. By April 2024, Gilgeous-Alexander signed a lucrative contract extension with the brand, which both confirmed a signature line and elevated him into an unprecedented role as creative director of Converse Basketball. With complete creative control, Gilgeous-Alexander steered the design process of his debut signature shoe, impressively drawing the initial sketch of the silhouette himself. SGA’s penmanship and vision ultimately materialized on the Converse SHAI 001 — a sleek, zip-up low-top, featuring a distinct wing-patterned shroud. Gilgeous-Alexander debuted the SHAI 001 during the 2025 NBA All-Star Weekend ahead of the shoe’s Fall 2025 retail release.', 'converse-shai') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (192, 3) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (891, 192, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/shai_gilgeous-alexander/converse_shai/converse_shai.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (700, 192, 'Converse SHAI 001', 2025, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/shai_gilgeous-alexander/converse_shai/models/converse_shai_001.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
