INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (148, 2, 'A''ja Wilson', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (193, 5, 148, 'Nike A''One', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/aja_wilson/nike_aone/nike_aone.jpg&w=712&h=480', 2025, 'Standard', 'After A’ja Wilson entered the WNBA in 2018, over time, one of the most-asked questions in women’s basketball became, “Why doesn’t A’ja have a signature shoe?” The answer finally arrived in May 2024, when Wilson was announced as Nike’s next WNBA signature headliner, having built a superstar resumé that made the case for her own shoe undeniable. A two-time WNBA champion and three-time league MVP, Wilson also notably became the first Black woman since Sheryl Swoopes in 2002 to receive a signature Nike Basketball shoe. It took Nike a full two years to complete the design of Wilson’s debut signature model, which draws its main inspiration from a pearl necklace her late grandmother gifted her when she was a kid. Releasing ahead of her seventh WNBA season, the Nike A’One was well worth the wait for Wilson. “I look at this shoe, and I’m like, ‘It’s perfect,” she told Andscape.', 'nike-aone') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_tag (shoe_id, tag_id) VALUES (193, 3) ON CONFLICT (shoe_id, tag_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (893, 193, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/aja_wilson/nike_aone/nike_aone.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (701, 193, 'Nike A''One', 2025, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/aja_wilson/nike_aone/models/nike_aone.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
