INSERT INTO brand (brand_id, name) VALUES (59, '741') ON CONFLICT DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (149, 1, 'Jaylen Brown', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (194, 59, 149, '741 Performance Rover', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jaylen_brown/741_performance_rover/741_performance_rover.jpg&w=712&h=480', 2024, 'Standard', 'Under the freedom of his self-built sneaker brand, Boston Celtics star forward Jaylen Brown spent more than two years working toward releasing his first-ever signature shoe. Ahead of the 2024-25 NBA season, Brown officially launched his brand, known as 741, as well as an introductory signature model, dubbed the Rover, just a few months removed from both winning his first NBA  title and being named Finals MVP. Brown actually teased the Rover on court during the 2024 Finals, when he warmed up in a nondescript sneaker that was immediately speculated to be his upcoming shoe, despite no original indication or confirmation of a specific brand behind it. Ultimately, Brown declared he declined over $50 million worth of endorsement offers from major footwear companies to forge his own path with 741 as a platform to release his debut shoe — designed by himself and for himself.', '741-performance-rover') ON CONFLICT (shoe_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (895, 194, NULL, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jaylen_brown/741_performance_rover/741_performance_rover.jpg&w=712&h=480', 'featured') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO shoe_model (model_id, shoe_id, model_name, release_year, image_url) VALUES (702, 194, '741 Performance Rover', 2024, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jaylen_brown/741_performance_rover/models/741_performance_rover.jpg&w=712&h=480') ON CONFLICT (model_id) DO NOTHING;
INSERT INTO shoe_image (image_id, shoe_id, model_id, image_url, image_type) VALUES (896, 194, 702, 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jaylen_brown/741_performance_rover/models/741_performance_rover.jpg&w=712&h=480', 'gallery') ON CONFLICT (image_id) DO NOTHING;
INSERT INTO athlete (athlete_id, league_id, full_name, active) VALUES (150, 1, 'Jacy Sheldon', true) ON CONFLICT DO NOTHING;
INSERT INTO shoe (shoe_id, brand_id, athlete_id, name, featured_image_url, intro_year, status_badge, description, espn_anchor) VALUES (195, 33, 150, 'HOLO Footwear JS01', 'https://a.espncdn.com/combiner/i?img=prod/styles/pagetype/otl/2024/24_vs_shoe-db/jacy_sheldon/holo_footwear_js01/holo_footwear_js01.jpg&w=712&h=480', 2025, 'Standard', 'The women’s signature landscape continued to expand in early 2025 when Jacy Sheldon was announced as the next WNBA player selected to receive her own shoe. The Connecticut Sun point guard signed with HOLO Footwear as the budding brand’s first women’s basketball endorser and second signature headliner, joining Isaac Okoro of the NBA’s Cleveland Cavaliers. With her debut JS:01 model, Sheldon became one of only four active WNBA players with a signature shoe, and just the 15th player in league history to earn the distinction.', 'holo-footwear-js01') ON CONFLICT (shoe_id) DO NOTHING;
