ON CONFLICT (name) DO NOTHING;


-- Base "User" Permissions (for all logged-in users)
('MANAGE_OWN_PROFILE', 'Allows user to update their personal info and password.'),
('USE_MESSAGING', 'Allows user to send/receive messages with other participants.'),

-- Student Permissions
('VIEW_LEAGUES', 'Allows user to browse and search available leagues and activities.'),
('REGISTER_FOR_LEAGUE', 'Allows user to register as an individual for a league.'),
('CREATE_TEAM', 'Allows user to create a new team as a captain.'),
('MANAGE_TEAM_INVITATIONS', 'Allows user to accept or decline invitations to a team.'),
('VIEW_OWN_SCHEDULE', 'Allows user to view their personal and team game schedule.'),
('VIEW_STANDINGS', 'Allows user to view league standings and team statistics.'),

-- School Admin Permissions
('MANAGE_FACILITIES', 'Allows user to C/R/U/D locations, fields, and courts.'),
('MANAGE_SCHEDULES', 'Allows user to C/R/U/D leagues, activities, and games.'),
('MANAGE_REGISTRATIONS', 'Allows user to view and approve team registrations.'),
('MANAGE_SCORES', 'Allows user to enter and confirm game scores.'),
('SEND_ANNOUNCEMENTS', 'Allows user to send messages to individuals, teams, and leagues.')
    ON CONFLICT (name) DO NOTHING;


-- --- Assign permissions to STUDENT role ---
-- Base permissions
((SELECT id FROM roles_demo WHERE name = 'STUDENT'), (SELECT id FROM permissions_demo WHERE name = 'MANAGE_OWN_PROFILE')),
((SELECT id FROM roles_demo WHERE name = 'STUDENT'), (SELECT id FROM permissions_demo WHERE name = 'USE_MESSAGING')),
-- Student-specific permissions
((SELECT id FROM roles_demo WHERE name = 'STUDENT'), (SELECT id FROM permissions_demo WHERE name = 'VIEW_LEAGUES')),
((SELECT id FROM roles_demo WHERE name = 'STUDENT'), (SELECT id FROM permissions_demo WHERE name = 'REGISTER_FOR_LEAGUE')),
((SELECT id FROM roles_demo WHERE name = 'STUDENT'), (SELECT id FROM permissions_demo WHERE name = 'CREATE_TEAM')),
((SELECT id FROM roles_demo WHERE name = 'STUDENT'), (SELECT id FROM permissions_demo WHERE name = 'MANAGE_TEAM_INVITATIONS')),
((SELECT id FROM roles_demo WHERE name = 'STUDENT'), (SELECT id FROM permissions_demo WHERE name = 'VIEW_OWN_SCHEDULE')),
((SELECT id FROM roles_demo WHERE name = 'STUDENT'), (SELECT id FROM permissions_demo WHERE name = 'VIEW_STANDINGS'))
    ON CONFLICT (role_id, permission_id) DO NOTHING;


-- --- Assign permissions to ADMIN role ---
-- Admins get all permissions: their own, plus all student permissions.
-- Base permissions
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'MANAGE_OWN_PROFILE')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'USE_MESSAGING')),
-- Student view permissions (Admins need to see what students see)
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'VIEW_LEAGUES')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'REGISTER_FOR_LEAGUE')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'CREATE_TEAM')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'MANAGE_TEAM_INVITATIONS')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'VIEW_OWN_SCHEDULE')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'VIEW_STANDINGS')),
-- Admin-specific permissions
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'MANAGE_FACILITIES')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'MANAGE_SCHEDULES')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'MANAGE_REGISTRATIONS')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'MANAGE_SCORES')),
((SELECT id FROM roles_demo WHERE name = 'SCHOOL_ADMIN'), (SELECT id FROM permissions_demo WHERE name = 'SEND_ANNOUNCEMENTS'))
    ON CONFLICT (role_id, permission_id) DO NOTHING;

ON CONFLICT (email) DO NOTHING;

-- Assign roles to users
ON CONFLICT (user_id, role_id) DO NOTHING;






































































































































































































